from pathlib import Path
import html
R=Path(__file__).resolve().parents[1];out=R/'renders/reference-rooms'
rooms=[('atico-creativo','Ático creativo','Techo inclinado, claraboya, escalera abierta y zona de pintura.'),('rincon-urbano','Rincón urbano','Ventanales en esquina, skyline, estantería abierta y dos pufs.'),('sala-control-gamer','Sala de control gamer','Escritorio en L, monitores, PC, juegos, colecciones y alfombra modular.'),('habitacion-invernadero','Habitación invernadero','Estructura acristalada, plantas, banco de cultivo, sillón y fuente.'),('estudio-musical','Estudio musical','Paneles acústicos, guitarras, teclado, vinilos y micrófono.'),('rincon-explorador','Rincón explorador','Bibliotecas, mapa, globo, telescopio, cámara y equipaje.')]
blocks=[]
for slug,title,desc in rooms:
 blocks.append(f'<article id="{slug}"><h2>{title}</h2><p>{desc}</p><a href="{slug}-review.png"><img src="{slug}-review.png" alt="Render Blender de {title}" loading="lazy"></a><details><summary>Ver acercamiento</summary><a href="{slug}-detail.png"><img src="{slug}-detail.png" alt="Detalle de {title}" loading="lazy"></a></details><a class="download" href="../../packages/assets/3d/source/rooms/reference-rebuild/{slug}-review.blend">Abrir archivo Blender</a></article>')
(out/'revision-habitaciones.html').write_text('''<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Compa Virtual · Revisión de habitaciones</title><style>body{margin:0;background:#f7f3ed;color:#172335;font:17px/1.5 system-ui}main{max-width:1200px;margin:auto;padding:32px 20px}h1{font-size:clamp(30px,5vw,52px);line-height:1.1}p{max-width:75ch;color:#536071}article{margin:52px 0 76px}img{display:block;width:100%;height:auto;border-radius:14px}h2{font-size:28px;margin-bottom:4px}a{color:#214e6c}summary,.download{display:inline-block;padding:14px 0;cursor:pointer}details img{max-width:850px}nav{display:flex;gap:20px;flex-wrap:wrap}footer{padding:24px 0}</style><main><h1>Seis habitaciones, seis espacios propios.</h1><p>Renders de escenas Blender editables. Versión de revisión: todavía no integrada ni optimizada para la app. Los acercamientos muestran la geometría real de cada archivo.</p><nav>'''+''.join(f'<a href="#{s}">{t}</a>' for s,t,d in rooms)+'</nav>'+''.join(blocks)+'<footer>Se conservan los modelos publicados anteriores. La navegación del personaje debe recalibrarse para estas distribuciones.</footer></main></html>',encoding='utf-8')
